 3→import java.util.Objects;
 4→
 5→/**
 6→ * An opaque token representing a registered table handle. Must be released via
 7→ * {@link HandleTracker#release(HandleRegistration)} when the handle is closed.
 8→ */
 9→final class HandleRegistration {
10→
11→    private final String tableName;
12→    private final String sourceId;
13→    private final StackTraceElement[] allocationSite;
14→    private volatile boolean invalidated;
15→
16→    HandleRegistration(String tableName, String sourceId, StackTraceElement[] allocationSite) {
17→        this.tableName = Objects.requireNonNull(tableName, "tableName must not be null");
18→        this.sourceId = Objects.requireNonNull(sourceId, "sourceId must not be null");
19→        this.allocationSite = allocationSite;
20→    }
21→
22→    String tableName() {
23→        return tableName;
24→    }
25→
26→    String sourceId() {
27→        return sourceId;
28→    }
29→
30→    StackTraceElement[] allocationSite() {
31→        return allocationSite;
32→    }
33→
34→    boolean isInvalidated() {
35→        return invalidated;
36→    }
37→
38→    void invalidate() {
39→        this.invalidated = true;
40→    }
41→}
