  1→package jlsm.engine.internal;
  2→
  3→import jlsm.engine.AllocationTracking;
  4→import jlsm.engine.EngineMetrics;
  5→import jlsm.engine.HandleEvictedException;
  6→
  7→import java.io.Closeable;
  8→import java.io.IOException;
  9→import java.util.Objects;
 10→
 11→/**
 12→ * Tracks open table handles per source, enforces configurable limits, and performs
 13→ * greedy-source-first eviction under pressure.
 14→ *
 15→ * <p>
 16→ * Governed by: {@code .decisions/engine-api-surface-design/adr.md}
 17→ */
 18→final class HandleTracker implements Closeable {
 19→
 20→    private final int maxHandlesPerSourcePerTable;
 21→    private final int maxHandlesPerTable;
 22→    private final int maxTotalHandles;
 23→    private final AllocationTracking allocationTracking;
 24→
 25→    private HandleTracker(Builder builder) {
 26→        assert builder.maxHandlesPerSourcePerTable > 0 : "maxHandlesPerSourcePerTable must be positive";
 27→        assert builder.maxHandlesPerTable > 0 : "maxHandlesPerTable must be positive";
 28→        assert builder.maxTotalHandles > 0 : "maxTotalHandles must be positive";
 29→        this.maxHandlesPerSourcePerTable = builder.maxHandlesPerSourcePerTable;
 30→        this.maxHandlesPerTable = builder.maxHandlesPerTable;
 31→        this.maxTotalHandles = builder.maxTotalHandles;
 32→        this.allocationTracking = Objects.requireNonNull(builder.allocationTracking,
 33→                "allocationTracking must not be null");
 34→    }
 35→
 36→    /**
 37→     * Returns a new builder for constructing a HandleTracker.
 38→     *
 39→     * @return a new builder; never null
 40→     */
 41→    static Builder builder() {
 42→        return new Builder();
 43→    }
 44→
 45→    /**
 46→     * Registers a new handle for the given table and source.
 47→     *
 48→     * @param tableName the table name; must not be null
 49→     * @param sourceId  the source identifier; must not be null
 50→     * @return a registration token that must be released when the handle is closed
 51→     */
 52→    HandleRegistration register(String tableName, String sourceId) {
 53→        Objects.requireNonNull(tableName, "tableName must not be null");
 54→        Objects.requireNonNull(sourceId, "sourceId must not be null");
 55→        throw new UnsupportedOperationException("Not implemented");
 56→    }
 57→
 58→    /**
 59→     * Releases a previously registered handle.
 60→     *
 61→     * @param registration the registration to release; must not be null
 62→     */
 63→    void release(HandleRegistration registration) {
 64→        Objects.requireNonNull(registration, "registration must not be null");
 65→        throw new UnsupportedOperationException("Not implemented");
 66→    }
 67→
 68→    /**
 69→     * Evicts handles if the table exceeds its handle limit, using greedy-source-first strategy.
 70→     *
 71→     * @param tableName the table to check; must not be null
 72→     */
 73→    void evictIfNeeded(String tableName) {
 74→        Objects.requireNonNull(tableName, "tableName must not be null");
 75→        throw new UnsupportedOperationException("Not implemented");
 76→    }
 77→
 78→    /**
 79→     * Invalidates all tracked handles with the given reason.
 80→     *
 81→     * @param reason the invalidation reason; must not be null
 82→     */
 83→    void invalidateAll(HandleEvictedException.Reason reason) {
 84→        Objects.requireNonNull(reason, "reason must not be null");
 85→        throw new UnsupportedOperationException("Not implemented");
 86→    }
 87→
 88→    /**
 89→     * Invalidates all tracked handles for a specific table.
 90→     *
 91→     * @param tableName the table name; must not be null
 92→     * @param reason    the invalidation reason; must not be null
 93→     */
 94→    void invalidateTable(String tableName, HandleEvictedException.Reason reason) {
 95→        Objects.requireNonNull(tableName, "tableName must not be null");
 96→        Objects.requireNonNull(reason, "reason must not be null");
 97→        throw new UnsupportedOperationException("Not implemented");
 98→    }
 99→
100→    /**
101→     * Returns a snapshot of current engine metrics.
102→     *
103→     * @return the current metrics; never null
104→     */
105→    EngineMetrics snapshot() {
106→        throw new UnsupportedOperationException("Not implemented");
107→    }
108→
109→    @Override
110→    public void close() throws IOException {
111→        throw new UnsupportedOperationException("Not implemented");
112→    }
113→
114→    /**
115→     * Builder for {@link HandleTracker}.
116→     */
117→    static final class Builder {
118→
119→        private int maxHandlesPerSourcePerTable = 16;
120→        private int maxHandlesPerTable = 64;
121→        private int maxTotalHandles = 1024;
122→        private AllocationTracking allocationTracking = AllocationTracking.OFF;
123→
124→        private Builder() {
125→        }
126→
127→        Builder maxHandlesPerSourcePerTable(int max) {
128→            assert max > 0 : "max must be positive";
129→            this.maxHandlesPerSourcePerTable = max;
130→            return this;
131→        }
132→
133→        Builder maxHandlesPerTable(int max) {
134→            assert max > 0 : "max must be positive";
135→            this.maxHandlesPerTable = max;
136→            return this;
137→        }
138→
139→        Builder maxTotalHandles(int max) {
140→            assert max > 0 : "max must be positive";
141→            this.maxTotalHandles = max;
142→            return this;
143→        }
144→
145→        Builder allocationTracking(AllocationTracking tracking) {
146→            Objects.requireNonNull(tracking, "tracking must not be null");
147→            this.allocationTracking = tracking;
148→            return this;
149→        }
150→
151→        HandleTracker build() {
152→            return new HandleTracker(this);
153→        }
154→    }
155→}
