  6→import java.io.Closeable;
  7→import java.io.IOException;
  8→import java.nio.file.Path;
  9→import java.util.Collection;
 10→import java.util.Objects;
 11→import java.util.Optional;
 12→
 13→/**
 14→ * Manages per-table directory layout, metadata persistence, and lazy table loading.
 15→ *
 16→ * <p>
 17→ * Each table lives in its own subdirectory under the engine root. The catalog scans
 18→ * the root directory on {@link #open()} to discover existing tables and builds lightweight
 19→ * metadata handles. Full table initialization is deferred until first access.
 20→ *
 21→ * <p>
 22→ * Governed by: {@code .decisions/table-catalog-persistence/adr.md}
 23→ */
 24→final class TableCatalog implements Closeable {
 25→
 26→    private final Path rootDir;
 27→
 28→    /**
 29→     * Constructs a new TableCatalog for the given root directory.
 30→     *
 31→     * @param rootDir the engine root directory; must not be null
 32→     */
 33→    TableCatalog(Path rootDir) {
 34→        this.rootDir = Objects.requireNonNull(rootDir, "rootDir must not be null");
 35→    }
 36→
 37→    /**
 38→     * Opens the catalog by scanning the root directory for existing table subdirectories.
 39→     * Builds lightweight metadata handles without fully initializing tables.
 40→     *
 41→     * @throws IOException if the root directory cannot be read or is corrupt
 42→     */
 43→    void open() throws IOException {
 44→        throw new UnsupportedOperationException("Not implemented");
 45→    }
 46→
 47→    /**
 48→     * Registers a new table by creating its subdirectory and metadata file.
 49→     *
 50→     * @param name   the table name; must not be null or empty
 51→     * @param schema the table schema; must not be null
 52→     * @return the metadata for the newly registered table
 53→     * @throws IOException if the table already exists or the directory cannot be created
 54→     */
 55→    TableMetadata register(String name, JlsmSchema schema) throws IOException {
 56→        Objects.requireNonNull(name, "name must not be null");
 57→        Objects.requireNonNull(schema, "schema must not be null");
 58→        if (name.isEmpty()) {
 59→            throw new IllegalArgumentException("name must not be empty");
 60→        }
 61→        throw new UnsupportedOperationException("Not implemented");
 62→    }
 63→
 64→    /**
 65→     * Unregisters a table by removing its subdirectory and all contained files.
 66→     *
 67→     * @param name the table name; must not be null or empty
 68→     * @throws IOException if the table does not exist or cannot be removed
 69→     */
 70→    void unregister(String name) throws IOException {
 71→        Objects.requireNonNull(name, "name must not be null");
 72→        if (name.isEmpty()) {
 73→            throw new IllegalArgumentException("name must not be empty");
 74→        }
 75→        throw new UnsupportedOperationException("Not implemented");
 76→    }
 77→
 78→    /**
 79→     * Returns metadata for a specific table, or empty if not registered.
 80→     *
 81→     * @param name the table name; must not be null
 82→     * @return an Optional containing the metadata, or empty if not found
 83→     */
 84→    Optional<TableMetadata> get(String name) {
 85→        Objects.requireNonNull(name, "name must not be null");
 86→        throw new UnsupportedOperationException("Not implemented");
 87→    }
 88→
 89→    /**
 90→     * Returns metadata for all known tables.
 91→     *
 92→     * @return an unmodifiable collection of table metadata; never null
 93→     */
 94→    Collection<TableMetadata> list() {
 95→        throw new UnsupportedOperationException("Not implemented");
 96→    }
 97→
 98→    /**
 99→     * Returns the directory path for a given table.
100→     *
101→     * @param name the table name; must not be null
102→     * @return the table's subdirectory path; never null
103→     */
104→    Path tableDirectory(String name) {
105→        Objects.requireNonNull(name, "name must not be null");
106→        throw new UnsupportedOperationException("Not implemented");
107→    }
108→
109→    /**
110→     * Returns true if the catalog is still loading (scanning the root directory).
111→     *
112→     * @return true if loading is in progress
113→     */
114→    boolean isLoading() {
115→        throw new UnsupportedOperationException("Not implemented");
116→    }
117→
118→    @Override
119→    public void close() throws IOException {
120→        throw new UnsupportedOperationException("Not implemented");
121→    }
122→}
