 1→package jlsm.engine;
 2→
 3→import java.util.Map;
 4→import java.util.Objects;
 5→
 6→/**
 7→ * A snapshot of engine-wide handle counts and statistics.
 8→ *
 9→ * <p>
10→ * Governed by: {@code .decisions/engine-api-surface-design/adr.md}
11→ *
12→ * @param tableCount             the number of registered tables
13→ * @param totalOpenHandles       the total number of open table handles across all tables
14→ * @param handlesPerTable        open handle count per table name; never null
15→ * @param handlesPerSourcePerTable open handle count per source per table; never null
16→ */
17→public record EngineMetrics(
18→        int tableCount,
19→        int totalOpenHandles,
20→        Map<String, Integer> handlesPerTable,
21→        Map<String, Map<String, Integer>> handlesPerSourcePerTable) {
22→
23→    public EngineMetrics {
24→        assert tableCount >= 0 : "tableCount must be non-negative";
25→        assert totalOpenHandles >= 0 : "totalOpenHandles must be non-negative";
26→        Objects.requireNonNull(handlesPerTable, "handlesPerTable must not be null");
27→        Objects.requireNonNull(handlesPerSourcePerTable, "handlesPerSourcePerTable must not be null");
28→        handlesPerTable = Map.copyOf(handlesPerTable);
29→        handlesPerSourcePerTable = Map.copyOf(handlesPerSourcePerTable);
30→    }
31→}
