 5→import java.time.Instant;
 6→import java.util.Objects;
 7→
 8→/**
 9→ * Metadata for a table managed by an {@link Engine}.
10→ *
11→ * <p>
12→ * Governed by: {@code .decisions/table-catalog-persistence/adr.md}
13→ *
14→ * @param name      the table name; never null
15→ * @param schema    the table schema; never null
16→ * @param createdAt the instant the table was created; never null
17→ * @param state     the current table state; never null
18→ */
19→public record TableMetadata(String name, JlsmSchema schema, Instant createdAt, TableState state) {
20→
21→    public TableMetadata {
22→        Objects.requireNonNull(name, "name must not be null");
23→        Objects.requireNonNull(schema, "schema must not be null");
24→        Objects.requireNonNull(createdAt, "createdAt must not be null");
25→        Objects.requireNonNull(state, "state must not be null");
26→        assert !name.isEmpty() : "name must not be empty";
27→    }
28→
29→    /**
30→     * The lifecycle state of a table.
31→     */
32→    public enum TableState {
33→        /** Table directory exists but full initialization has not completed. */
34→        LOADING,
35→        /** Table is fully initialized and ready for operations. */
36→        READY,
37→        /** Table has been dropped and is no longer accessible. */
38→        DROPPED,
39→        /** Table encountered an error during initialization or operation. */
40→        ERROR
41→    }
42→}
