12→/**
13→ * Describes the structure of documents stored in a {@link JlsmTable}.
14→ *
15→ * <p>
16→ * A schema has a name, a version, an ordered list of {@link FieldDefinition}s, and a maximum
17→ * nesting depth limit for object fields.
18→ */
19→public final class JlsmSchema {
20→
21→    private static final int DEFAULT_MAX_DEPTH = 10;
22→    private static final int ABSOLUTE_MAX_DEPTH = 25;
23→
24→    private final String name;
25→    private final int version;
26→    private final List<FieldDefinition> fields;
27→    private final int maxDepth;
28→    private final Map<String, Integer> fieldIndexMap;
29→
30→    private JlsmSchema(String name, int version, List<FieldDefinition> fields, int maxDepth) {
31→        assert name != null : "name must not be null";
32→        assert fields != null : "fields must not be null";
33→        assert maxDepth >= 0 && maxDepth <= ABSOLUTE_MAX_DEPTH : "maxDepth out of range";
34→
35→        this.name = name;
36→        this.version = version;
37→        this.fields = List.copyOf(fields);
38→        this.maxDepth = maxDepth;
39→
40→        // Build field index map for O(1) lookup
41→        final Map<String, Integer> indexMap = new HashMap<>(fields.size() * 2);
42→        for (int i = 0; i < fields.size(); i++) {
43→            indexMap.put(fields.get(i).name(), i);
44→        }
45→        this.fieldIndexMap = Map.copyOf(indexMap);
46→    }
47→
48→    /** Returns the schema name. */
49→    public String name() {
50→        return name;
51→    }
52→
53→    /** Returns the schema version. */
54→    public int version() {
55→        return version;
56→    }
57→
58→    /** Returns an unmodifiable ordered list of field definitions. */
59→    public List<FieldDefinition> fields() {
60→        return fields;
61→    }
62→
63→    /** Returns the maximum allowed nesting depth for object fields. */
64→    public int maxDepth() {
65→        return maxDepth;
66→    }
67→
68→    /**
69→     * Returns the zero-based index of the field with the given name, or {@code -1} if no such field
70→     * exists.
71→     *
72→     * @param name the field name to look up; must not be null
73→     * @return the field index, or -1 if not found
74→     */
75→    public int fieldIndex(String name) {
76→        Objects.requireNonNull(name, "name must not be null");
77→        return fieldIndexMap.getOrDefault(name, -1);
78→    }
79→
80→    /**

 80→    /**
 81→     * Creates a new {@link Builder} for a schema with the given name and version.
 82→     *
 83→     * @param name the schema name; must not be null
 84→     * @param version the schema version
 85→     * @return a new Builder
 86→     */
 87→    public static Builder builder(String name, int version) {
 88→        Objects.requireNonNull(name, "name must not be null");
 89→        return new Builder(name, version, 0, DEFAULT_MAX_DEPTH, null);
 90→    }
 91→
 92→    /**
 93→     * Builder for {@link JlsmSchema}.
 94→     *
 95→     * <p>
 96→     * The builder tracks a current nesting depth; {@link #objectField} creates a nested builder at
 97→     * {@code depth + 1}. {@link #build()} validates that no level exceeds the configured
 98→     * {@code maxDepth}.
 99→     */
100→    public static final class Builder {
101→
102→        private final String name;
103→        private final int version;
104→        private final int currentDepth;
105→        private final List<FieldDefinition> fields = new ArrayList<>();
106→
107→        // maxDepth is tracked on the root builder; nested builders reference the root
108→        private int maxDepth;
109→        // parentBuilder is null for the root; non-null for nested builders
110→        private final Builder rootBuilder;
111→
112→        private Builder(String name, int version, int currentDepth, int maxDepth,
113→                Builder rootBuilder) {
114→            this.name = name;
115→            this.version = version;
116→            this.currentDepth = currentDepth;
117→            this.maxDepth = maxDepth;
118→            this.rootBuilder = rootBuilder;
119→        }
120→
121→        /**
122→         * Adds a primitive or array field to this schema level.
123→         *
124→         * @param name the field name; must not be null
125→         * @param type the field type; must not be null
126→         * @return this builder
127→         */
128→        public Builder field(String name, FieldType type) {
129→            Objects.requireNonNull(name, "name must not be null");
130→            Objects.requireNonNull(type, "type must not be null");
131→            assert name != null : "name must not be null";
132→            assert type != null : "type must not be null";
133→            fields.add(new FieldDefinition(name, type));
134→            return this;
135→        }
136→
137→        /**
138→         * Adds a primitive or array field with an explicit encryption specification.
139→         *
140→         * @param name the field name; must not be null
141→         * @param type the field type; must not be null
142→         * @param encryption the encryption spec; must not be null
143→         * @return this builder
144→         */
145→        public Builder field(String name, FieldType type, EncryptionSpec encryption) {
146→            Objects.requireNonNull(name, "name must not be null");
147→            Objects.requireNonNull(type, "type must not be null");
148→            Objects.requireNonNull(encryption, "encryption must not be null");
149→            assert name != null : "name must not be null";
150→            assert type != null : "type must not be null";
151→            assert encryption != null : "encryption must not be null";
152→            fields.add(new FieldDefinition(name, type, encryption));
153→            return this;
154→        }
