package jlsm.engine.internal;

import jlsm.engine.AllocationTracking;
import jlsm.engine.EngineMetrics;
import jlsm.engine.HandleEvictedException;

import java.io.Closeable;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Tracks open table handles per source, enforces configurable limits, and performs
 * greedy-source-first eviction under pressure.
 *
 * <p>
 * Thread-safe: all mutable state is guarded by either ConcurrentHashMap or synchronized blocks.
 *
 * <p>
 * Governed by: {@code .decisions/engine-api-surface-design/adr.md}
 */
final class HandleTracker implements Closeable {

    private final int maxHandlesPerSourcePerTable;
    private final int maxHandlesPerTable;
    private final int maxTotalHandles;
    private final AllocationTracking allocationTracking;
    private final AtomicBoolean closed = new AtomicBoolean(false);

    /**
     * Map from tableName -> (sourceId -> list of registrations in insertion order).
     * The outer ConcurrentHashMap provides thread-safe table-level access.
     * Inner maps and lists are guarded by synchronizing on the per-table map.
     */
    private final ConcurrentHashMap<String, Map<String, List<HandleRegistration>>> tableHandles =
            new ConcurrentHashMap<>();

    private HandleTracker(Builder builder) {
        assert builder.maxHandlesPerSourcePerTable > 0 : "maxHandlesPerSourcePerTable must be positive";
        assert builder.maxHandlesPerTable > 0 : "maxHandlesPerTable must be positive";
        assert builder.maxTotalHandles > 0 : "maxTotalHandles must be positive";
        this.maxHandlesPerSourcePerTable = builder.maxHandlesPerSourcePerTable;
        this.maxHandlesPerTable = builder.maxHandlesPerTable;
        this.maxTotalHandles = builder.maxTotalHandles;
        this.allocationTracking = Objects.requireNonNull(builder.allocationTracking,
                "allocationTracking must not be null");
    }

    /**
     * Returns a new builder for constructing a HandleTracker.
     *
     * @return a new builder; never null
     */
    static Builder builder() {
        return new Builder();
    }

    /**
     * Registers a new handle for the given table and source.
     *
     * @param tableName the table name; must not be null
     * @param sourceId  the source identifier; must not be null
     * @return a registration token that must be released when the handle is closed
     */
    HandleRegistration register(String tableName, String sourceId) {
        Objects.requireNonNull(tableName, "tableName must not be null");
        Objects.requireNonNull(sourceId, "sourceId must not be null");

        final StackTraceElement[] allocationSite = switch (allocationTracking) {
            case OFF, CALLER_TAG -> null;
            case FULL_STACK -> Thread.currentThread().getStackTrace();
        };

        final HandleRegistration registration = new HandleRegistration(tableName, sourceId, allocationSite);

        final Map<String, List<HandleRegistration>> sourceMap =
                tableHandles.computeIfAbsent(tableName, k -> new LinkedHashMap<>());
        synchronized (sourceMap) {
            sourceMap.computeIfAbsent(sourceId, k -> new ArrayList<>()).add(registration);
        }

        return registration;
    }

    /**
     * Releases a previously registered handle. Idempotent — releasing an already-released
     * or invalidated registration is a no-op.
     *
     * @param registration the registration to release; must not be null
     */
    void release(HandleRegistration registration) {
        Objects.requireNonNull(registration, "registration must not be null");

        final String tableName = registration.tableName();
        final String sourceId = registration.sourceId();

        final Map<String, List<HandleRegistration>> sourceMap = tableHandles.get(tableName);
        if (sourceMap == null) {
            return;
        }
        synchronized (sourceMap) {
            final List<HandleRegistration> regs = sourceMap.get(sourceId);
            if (regs == null) {
                return;
            }
            regs.remove(registration);
            if (regs.isEmpty()) {
                sourceMap.remove(sourceId);
            }
            if (sourceMap.isEmpty()) {
                tableHandles.remove(tableName);
            }
        }
    }

    /**
     * Evicts handles if the table exceeds its handle limit, using greedy-source-first strategy.
     * Also checks total handle limit across all tables.
     *
     * @param tableName the table to check; must not be null
     */
    void evictIfNeeded(String tableName) {
        Objects.requireNonNull(tableName, "tableName must not be null");

        final Map<String, List<HandleRegistration>> sourceMap = tableHandles.get(tableName);
        if (sourceMap == null) {
            return;
        }

        synchronized (sourceMap) {
            // Check per-source-per-table limits
            for (final Map.Entry<String, List<HandleRegistration>> entry : sourceMap.entrySet()) {
                final List<HandleRegistration> regs = entry.getValue();
                while (regs.size() > maxHandlesPerSourcePerTable) {
                    evictOldest(regs, HandleEvictedException.Reason.EVICTION);
                }
            }

            // Check per-table limit
            int tableTotal = countTableHandles(sourceMap);
            while (tableTotal > maxHandlesPerTable) {
                evictFromGreediestSource(sourceMap, HandleEvictedException.Reason.EVICTION);
                tableTotal = countTableHandles(sourceMap);
            }
        }

        // Check total limit across all tables — evict from this table's greediest source
        int total = countTotalHandles();
        while (total > maxTotalHandles) {
            synchronized (sourceMap) {
                if (countTableHandles(sourceMap) == 0) {
                    break;
                }
                evictFromGreediestSource(sourceMap, HandleEvictedException.Reason.EVICTION);
            }
            total = countTotalHandles();
        }
    }

    /**
     * Invalidates all tracked handles with the given reason.
     *
     * @param reason the invalidation reason; must not be null
     */
    void invalidateAll(HandleEvictedException.Reason reason) {
        Objects.requireNonNull(reason, "reason must not be null");

        for (final Map.Entry<String, Map<String, List<HandleRegistration>>> tableEntry : tableHandles.entrySet()) {
            final Map<String, List<HandleRegistration>> sourceMap = tableEntry.getValue();
            synchronized (sourceMap) {
                for (final List<HandleRegistration> regs : sourceMap.values()) {
                    for (final HandleRegistration reg : regs) {
                        reg.invalidate();
                    }
                }
                sourceMap.clear();
            }
        }
        tableHandles.clear();
    }

    /**
     * Invalidates all tracked handles for a specific table.
     *
     * @param tableName the table name; must not be null
     * @param reason    the invalidation reason; must not be null
     */
    void invalidateTable(String tableName, HandleEvictedException.Reason reason) {
        Objects.requireNonNull(tableName, "tableName must not be null");
        Objects.requireNonNull(reason, "reason must not be null");

        final Map<String, List<HandleRegistration>> sourceMap = tableHandles.remove(tableName);
        if (sourceMap == null) {
            return;
        }
        synchronized (sourceMap) {
            for (final List<HandleRegistration> regs : sourceMap.values()) {
                for (final HandleRegistration reg : regs) {
                    reg.invalidate();
                }
            }
            sourceMap.clear();
        }
    }

    /**
     * Returns a snapshot of current engine metrics.
     *
     * @return the current metrics; never null
     */
    EngineMetrics snapshot() {
        final Map<String, Integer> handlesPerTable = new HashMap<>();
        final Map<String, Map<String, Integer>> handlesPerSourcePerTable = new HashMap<>();
        int totalOpenHandles = 0;

        for (final Map.Entry<String, Map<String, List<HandleRegistration>>> tableEntry : tableHandles.entrySet()) {
            final String tableName = tableEntry.getKey();
            final Map<String, List<HandleRegistration>> sourceMap = tableEntry.getValue();
            int tableTotal = 0;
            final Map<String, Integer> sourceCountMap = new HashMap<>();

            synchronized (sourceMap) {
                for (final Map.Entry<String, List<HandleRegistration>> sourceEntry : sourceMap.entrySet()) {
                    final int count = sourceEntry.getValue().size();
                    if (count > 0) {
                        sourceCountMap.put(sourceEntry.getKey(), count);
                        tableTotal += count;
                    }
                }
            }

            if (tableTotal > 0) {
                handlesPerTable.put(tableName, tableTotal);
                handlesPerSourcePerTable.put(tableName, Map.copyOf(sourceCountMap));
                totalOpenHandles += tableTotal;
            }
        }

        final int tableCount = handlesPerTable.size();
        return new EngineMetrics(tableCount, totalOpenHandles, handlesPerTable, handlesPerSourcePerTable);
    }

    @Override
    public void close() throws IOException {
        if (closed.compareAndSet(false, true)) {
            invalidateAll(HandleEvictedException.Reason.ENGINE_SHUTDOWN);
        }
    }

    // ---- Private helpers ----

    private static int countTableHandles(Map<String, List<HandleRegistration>> sourceMap) {
        int count = 0;
        for (final List<HandleRegistration> regs : sourceMap.values()) {
            count += regs.size();
        }
        return count;
    }

    private int countTotalHandles() {
        int total = 0;
        for (final Map<String, List<HandleRegistration>> sourceMap : tableHandles.values()) {
            synchronized (sourceMap) {
                total += countTableHandles(sourceMap);
            }
        }
        return total;
    }

    /**
     * Evicts the oldest handle from the source with the most handles (greedy-source-first).
     */
    private static void evictFromGreediestSource(Map<String, List<HandleRegistration>> sourceMap,
                                                  HandleEvictedException.Reason reason) {
        String greediest = null;
        int maxCount = 0;
        for (final Map.Entry<String, List<HandleRegistration>> entry : sourceMap.entrySet()) {
            final int count = entry.getValue().size();
            if (count > maxCount) {
                maxCount = count;
                greediest = entry.getKey();
            }
        }
        if (greediest == null) {
            return;
        }
        final List<HandleRegistration> regs = sourceMap.get(greediest);
        assert regs != null && !regs.isEmpty() : "greediest source must have registrations";
        evictOldest(regs, reason);
        if (regs.isEmpty()) {
            sourceMap.remove(greediest);
        }
    }

    /**
     * Evicts the oldest (first) registration from the list and marks it invalidated.
     */
    private static void evictOldest(List<HandleRegistration> regs, HandleEvictedException.Reason reason) {
        assert !regs.isEmpty() : "cannot evict from empty list";
        final HandleRegistration victim = regs.removeFirst();
        victim.invalidate();
    }

    /**
     * Builder for {@link HandleTracker}.
     */
    static final class Builder {

        private int maxHandlesPerSourcePerTable = 16;
        private int maxHandlesPerTable = 64;
        private int maxTotalHandles = 1024;
        private AllocationTracking allocationTracking = AllocationTracking.OFF;

        private Builder() {
        }

        Builder maxHandlesPerSourcePerTable(int max) {
            assert max > 0 : "max must be positive";
            this.maxHandlesPerSourcePerTable = max;
            return this;
        }

        Builder maxHandlesPerTable(int max) {
            assert max > 0 : "max must be positive";
            this.maxHandlesPerTable = max;
            return this;
        }

        Builder maxTotalHandles(int max) {
            assert max > 0 : "max must be positive";
            this.maxTotalHandles = max;
            return this;
        }

        Builder allocationTracking(AllocationTracking tracking) {
            Objects.requireNonNull(tracking, "tracking must not be null");
            this.allocationTracking = tracking;
            return this;
        }

        HandleTracker build() {
            return new HandleTracker(this);
        }
    }
}

package jlsm.engine.internal;

import jlsm.engine.TableMetadata;
import jlsm.table.JlsmSchema;

import java.io.Closeable;
import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.Collection;
import java.util.Collections;
import java.util.Objects;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Manages per-table directory layout, metadata persistence, and lazy table loading.
 *
 * <p>
 * Each table lives in its own subdirectory under the engine root. The catalog scans
 * the root directory on {@link #open()} to discover existing tables and builds lightweight
 * metadata handles. Full table initialization is deferred until first access.
 *
 * <p>
 * Governed by: {@code .decisions/table-catalog-persistence/adr.md}
 */
final class TableCatalog implements Closeable {

    private static final String METADATA_FILE = "table.meta";
    private static final int MAGIC = 0x4A4C534D; // "JLSM"

    private final Path rootDir;
    private final ConcurrentHashMap<String, TableMetadata> tables = new ConcurrentHashMap<>();
    private volatile boolean loading = true;
    private final AtomicBoolean closed = new AtomicBoolean(false);

    /**
     * Constructs a new TableCatalog for the given root directory.
     *
     * @param rootDir the engine root directory; must not be null
     */
    TableCatalog(Path rootDir) {
        this.rootDir = Objects.requireNonNull(rootDir, "rootDir must not be null");
    }

    /**
     * Opens the catalog by scanning the root directory for existing table subdirectories.
     * Builds lightweight metadata handles without fully initializing tables.
     * Creates the root directory if it does not exist.
     *
     * @throws IOException if the root directory cannot be read or is corrupt
     */
    void open() throws IOException {
        if (!Files.exists(rootDir)) {
            Files.createDirectories(rootDir);
        }

        try (final DirectoryStream<Path> stream = Files.newDirectoryStream(rootDir)) {
            for (final Path entry : stream) {
                if (!Files.isDirectory(entry)) {
                    continue;
                }
                final String tableName = entry.getFileName().toString();
                final Path metadataPath = entry.resolve(METADATA_FILE);

                if (!Files.exists(metadataPath)) {
                    // Partial creation cleanup: directory exists but no metadata file
                    deleteDirectoryTree(entry);
                    continue;
                }

                try {
                    final TableMetadata metadata = readMetadata(tableName, metadataPath);
                    tables.put(tableName, metadata);
                } catch (IOException e) {
                    // Corrupt metadata — clean up
                    deleteDirectoryTree(entry);
                }
            }
        }

        loading = false;
    }

    /**
     * Registers a new table by creating its subdirectory and metadata file.
     *
     * @param name   the table name; must not be null or empty
     * @param schema the table schema; must not be null
     * @return the metadata for the newly registered table
     * @throws IOException if the table already exists or the directory cannot be created
     */
    TableMetadata register(String name, JlsmSchema schema) throws IOException {
        Objects.requireNonNull(name, "name must not be null");
        Objects.requireNonNull(schema, "schema must not be null");
        if (name.isEmpty()) {
            throw new IllegalArgumentException("name must not be empty");
        }

        if (tables.containsKey(name)) {
            throw new IOException("Table already exists: " + name);
        }

        final Path tableDir = rootDir.resolve(name);
        Files.createDirectories(tableDir);

        final Instant createdAt = Instant.now();
        final TableMetadata metadata = new TableMetadata(name, schema, createdAt, TableMetadata.TableState.READY);

        writeMetadata(tableDir.resolve(METADATA_FILE), metadata);

        final TableMetadata previous = tables.putIfAbsent(name, metadata);
        if (previous != null) {
            // Concurrent registration — clean up and throw
            deleteDirectoryTree(tableDir);
            throw new IOException("Table already exists (concurrent registration): " + name);
        }

        return metadata;
    }

    /**
     * Unregisters a table by removing its subdirectory and all contained files.
     *
     * @param name the table name; must not be null or empty
     * @throws IOException if the table does not exist or cannot be removed
     */
    void unregister(String name) throws IOException {
        Objects.requireNonNull(name, "name must not be null");
        if (name.isEmpty()) {
            throw new IllegalArgumentException("name must not be empty");
        }

        final TableMetadata removed = tables.remove(name);
        if (removed == null) {
            throw new IOException("Table does not exist: " + name);
        }

        final Path tableDir = rootDir.resolve(name);
        if (Files.exists(tableDir)) {
            deleteDirectoryTree(tableDir);
        }
    }

    /**
     * Returns metadata for a specific table, or empty if not registered.
     *
     * @param name the table name; must not be null
     * @return an Optional containing the metadata, or empty if not found
     */
    Optional<TableMetadata> get(String name) {
        Objects.requireNonNull(name, "name must not be null");
        return Optional.ofNullable(tables.get(name));
    }

    /**
     * Returns metadata for all known tables.
     *
     * @return an unmodifiable collection of table metadata; never null
     */
    Collection<TableMetadata> list() {
        return Collections.unmodifiableCollection(tables.values());
    }

    /**
     * Returns the directory path for a given table.
     *
     * @param name the table name; must not be null
     * @return the table's subdirectory path; never null
     */
    Path tableDirectory(String name) {
        Objects.requireNonNull(name, "name must not be null");
        return rootDir.resolve(name);
    }

    /**
     * Returns true if the catalog is still loading (scanning the root directory).
     *
     * @return true if loading is in progress
     */
    boolean isLoading() {
        return loading;
    }

    @Override
    public void close() throws IOException {
        if (closed.compareAndSet(false, true)) {
            tables.clear();
        }
    }

    // ---- Private helpers ----

    /**
     * Writes table metadata to a binary file.
     * Format: magic (4 bytes) | schema-name (UTF) | schema-version (int) | field-count (int) | created-at-millis (long)
     */
    private static void writeMetadata(Path path, TableMetadata metadata) throws IOException {
        assert metadata != null : "metadata must not be null";
        try (final DataOutputStream out = new DataOutputStream(Files.newOutputStream(path))) {
            out.writeInt(MAGIC);
            out.writeUTF(metadata.schema().name());
            out.writeInt(metadata.schema().version());
            out.writeInt(metadata.schema().fields().size());
            out.writeLong(metadata.createdAt().toEpochMilli());
        }
    }

    /**
     * Reads minimal metadata from a binary file. Returns a TableMetadata with LOADING state
     * and a skeleton JlsmSchema (name and version only, no fields).
     */
    private static TableMetadata readMetadata(String tableName, Path path) throws IOException {
        assert tableName != null : "tableName must not be null";
        assert path != null : "path must not be null";
        try (final DataInputStream in = new DataInputStream(Files.newInputStream(path))) {
            final int magic = in.readInt();
            if (magic != MAGIC) {
                throw new IOException("Invalid metadata magic: 0x" + Integer.toHexString(magic));
            }
            final String schemaName = in.readUTF();
            final int schemaVersion = in.readInt();
            final int fieldCount = in.readInt(); // read but not used for reconstruction
            final long createdAtMillis = in.readLong();

            // Build skeleton schema — name and version only
            final JlsmSchema skeleton = JlsmSchema.builder(schemaName, schemaVersion).build();
            final Instant createdAt = Instant.ofEpochMilli(createdAtMillis);

            return new TableMetadata(tableName, skeleton, createdAt, TableMetadata.TableState.LOADING);
        }
    }

    /**
     * Recursively deletes a directory and all its contents.
     * Uses an iterative approach (depth-first via walkFileTree).
     */
    private static void deleteDirectoryTree(Path root) throws IOException {
        assert root != null : "root must not be null";
        if (!Files.exists(root)) {
            return;
        }
        // Walk the tree and collect paths, then delete in reverse order (children first)
        final java.util.List<Path> paths = new java.util.ArrayList<>();
        try (final var walker = Files.walk(root)) {
            walker.forEach(paths::add);
        }
        // Delete in reverse order so children are deleted before parents
        for (int i = paths.size() - 1; i >= 0; i--) {
            Files.deleteIfExists(paths.get(i));
        }
    }
}

