 66→    /**
 67→     * Registers a new handle for the given table and source.
 68→     *
 69→     * @param tableName the table name; must not be null
 70→     * @param sourceId  the source identifier; must not be null
 71→     * @return a registration token that must be released when the handle is closed
 72→     */
 73→    HandleRegistration register(String tableName, String sourceId) {
 74→        Objects.requireNonNull(tableName, "tableName must not be null");
 75→        Objects.requireNonNull(sourceId, "sourceId must not be null");
 76→
 77→        final StackTraceElement[] allocationSite = switch (allocationTracking) {
 78→            case OFF, CALLER_TAG -> null;
 79→            case FULL_STACK -> Thread.currentThread().getStackTrace();
 80→        };
 81→
 82→        final HandleRegistration registration = new HandleRegistration(tableName, sourceId, allocationSite);
 83→
 84→        final Map<String, List<HandleRegistration>> sourceMap =
 85→                tableHandles.computeIfAbsent(tableName, k -> new LinkedHashMap<>());
 86→        synchronized (sourceMap) {
 87→            sourceMap.computeIfAbsent(sourceId, k -> new ArrayList<>()).add(registration);
 88→        }
 89→
 90→        return registration;
 91→    }
 92→
 93→    /**
 94→     * Releases a previously registered handle. Idempotent — releasing an already-released
 95→     * or invalidated registration is a no-op.
 96→     *
 97→     * @param registration the registration to release; must not be null
 98→     */
 99→    void release(HandleRegistration registration) {
100→        Objects.requireNonNull(registration, "registration must not be null");
101→
102→        final String tableName = registration.tableName();
103→        final String sourceId = registration.sourceId();
104→
105→        final Map<String, List<HandleRegistration>> sourceMap = tableHandles.get(tableName);
106→        if (sourceMap == null) {
107→            return;
108→        }
109→        synchronized (sourceMap) {
110→            final List<HandleRegistration> regs = sourceMap.get(sourceId);
111→            if (regs == null) {
112→                return;
113→            }
114→            regs.remove(registration);
115→            if (regs.isEmpty()) {
116→                sourceMap.remove(sourceId);
117→            }
118→            if (sourceMap.isEmpty()) {
119→                tableHandles.remove(tableName);
120→            }
121→        }
122→    }
123→
124→    /**
125→     * Evicts handles if the table exceeds its handle limit, using greedy-source-first strategy.
126→     * Also checks total handle limit across all tables.
127→     *
128→     * @param tableName the table to check; must not be null
129→     */
130→    void evictIfNeeded(String tableName) {
131→        Objects.requireNonNull(tableName, "tableName must not be null");
132→
133→        final Map<String, List<HandleRegistration>> sourceMap = tableHandles.get(tableName);
134→        if (sourceMap == null) {
135→            return;
136→        }
137→
138→        synchronized (sourceMap) {
139→            // Check per-source-per-table limits
140→            for (final Map.Entry<String, List<HandleRegistration>> entry : sourceMap.entrySet()) {
141→                final List<HandleRegistration> regs = entry.getValue();
142→                while (regs.size() > maxHandlesPerSourcePerTable) {
143→                    evictOldest(regs, HandleEvictedException.Reason.EVICTION);
144→                }
145→            }
146→
147→            // Check per-table limit
148→            int tableTotal = countTableHandles(sourceMap);
149→            while (tableTotal > maxHandlesPerTable) {
150→                evictFromGreediestSource(sourceMap, HandleEvictedException.Reason.EVICTION);
151→                tableTotal = countTableHandles(sourceMap);
152→            }
153→        }
154→
155→        // Check total limit across all tables — evict from this table's greediest source
156→        int total = countTotalHandles();
157→        while (total > maxTotalHandles) {
158→            synchronized (sourceMap) {
159→                if (countTableHandles(sourceMap) == 0) {
160→                    break;
161→                }
162→                evictFromGreediestSource(sourceMap, HandleEvictedException.Reason.EVICTION);
163→            }
164→            total = countTotalHandles();
165→        }
166→    }
167→
168→    /**
169→     * Invalidates all tracked handles with the given reason.
170→     *
171→     * @param reason the invalidation reason; must not be null
172→     */
173→    void invalidateAll(HandleEvictedException.Reason reason) {
174→        Objects.requireNonNull(reason, "reason must not be null");
175→
176→        for (final Map.Entry<String, Map<String, List<HandleRegistration>>> tableEntry : tableHandles.entrySet()) {
177→            final Map<String, List<HandleRegistration>> sourceMap = tableEntry.getValue();
178→            synchronized (sourceMap) {
179→                for (final List<HandleRegistration> regs : sourceMap.values()) {
180→                    for (final HandleRegistration reg : regs) {
181→                        reg.invalidate();
182→                    }
183→                }
184→                sourceMap.clear();
185→            }
186→        }
187→        tableHandles.clear();
188→    }
189→
190→    /**
191→     * Invalidates all tracked handles for a specific table.
192→     *
193→     * @param tableName the table name; must not be null
194→     * @param reason    the invalidation reason; must not be null
195→     */
196→    void invalidateTable(String tableName, HandleEvictedException.Reason reason) {
197→        Objects.requireNonNull(tableName, "tableName must not be null");
198→        Objects.requireNonNull(reason, "reason must not be null");
199→
200→        final Map<String, List<HandleRegistration>> sourceMap = tableHandles.remove(tableName);
201→        if (sourceMap == null) {
202→            return;
203→        }
204→        synchronized (sourceMap) {
205→            for (final List<HandleRegistration> regs : sourceMap.values()) {
206→                for (final HandleRegistration reg : regs) {
207→                    reg.invalidate();
208→                }
209→            }
210→            sourceMap.clear();
211→        }
212→    }
213→
214→    /**
215→     * Returns a snapshot of current engine metrics.
216→     *
217→     * @return the current metrics; never null
218→     */
219→    EngineMetrics snapshot() {
220→        final Map<String, Integer> handlesPerTable = new HashMap<>();
221→        final Map<String, Map<String, Integer>> handlesPerSourcePerTable = new HashMap<>();
222→        int totalOpenHandles = 0;
223→
224→        for (final Map.Entry<String, Map<String, List<HandleRegistration>>> tableEntry : tableHandles.entrySet()) {
225→            final String tableName = tableEntry.getKey();
226→            final Map<String, List<HandleRegistration>> sourceMap = tableEntry.getValue();
227→            int tableTotal = 0;
228→            final Map<String, Integer> sourceCountMap = new HashMap<>();
229→
230→            synchronized (sourceMap) {
231→                for (final Map.Entry<String, List<HandleRegistration>> sourceEntry : sourceMap.entrySet()) {
232→                    final int count = sourceEntry.getValue().size();
233→                    if (count > 0) {
234→                        sourceCountMap.put(sourceEntry.getKey(), count);
235→                        tableTotal += count;
236→                    }
237→                }
238→            }
239→
240→            if (tableTotal > 0) {
241→                handlesPerTable.put(tableName, tableTotal);
242→                handlesPerSourcePerTable.put(tableName, Map.copyOf(sourceCountMap));
243→                totalOpenHandles += tableTotal;
244→            }
245→        }
246→
247→        final int tableCount = handlesPerTable.size();
248→        return new EngineMetrics(tableCount, totalOpenHandles, handlesPerTable, handlesPerSourcePerTable);
249→    }
250→
251→    @Override
252→    public void close() throws IOException {
253→        if (closed.compareAndSet(false, true)) {
254→            invalidateAll(HandleEvictedException.Reason.ENGINE_SHUTDOWN);
255→        }
256→    }
257→
258→    // ---- Private helpers ----
259→
260→    private static int countTableHandles(Map<String, List<HandleRegistration>> sourceMap) {
261→        int count = 0;
262→        for (final List<HandleRegistration> regs : sourceMap.values()) {
263→            count += regs.size();
264→        }
265→        return count;
266→    }
267→
268→    private int countTotalHandles() {
269→        int total = 0;
270→        for (final Map<String, List<HandleRegistration>> sourceMap : tableHandles.values()) {
271→            synchronized (sourceMap) {
272→                total += countTableHandles(sourceMap);
273→            }
274→        }
275→        return total;
276→    }
277→
278→    /**
279→     * Evicts the oldest handle from the source with the most handles (greedy-source-first).
280→     */
281→    private static void evictFromGreediestSource(Map<String, List<HandleRegistration>> sourceMap,
282→                                                  HandleEvictedException.Reason reason) {
283→        String greediest = null;
284→        int maxCount = 0;
285→        for (final Map.Entry<String, List<HandleRegistration>> entry : sourceMap.entrySet()) {
286→            final int count = entry.getValue().size();
287→            if (count > maxCount) {
288→                maxCount = count;
289→                greediest = entry.getKey();
290→            }
291→        }
292→        if (greediest == null) {
293→            return;
294→        }
295→        final List<HandleRegistration> regs = sourceMap.get(greediest);
296→        assert regs != null && !regs.isEmpty() : "greediest source must have registrations";
297→        evictOldest(regs, reason);
298→        if (regs.isEmpty()) {
299→            sourceMap.remove(greediest);
300→        }
301→    }
302→
303→    /**
304→     * Evicts the oldest (first) registration from the list and marks it invalidated.
305→     */
306→    private static void evictOldest(List<HandleRegistration> regs, HandleEvictedException.Reason reason) {
307→        assert !regs.isEmpty() : "cannot evict from empty list";
308→        final HandleRegistration victim = regs.removeFirst();
309→        victim.invalidate();
310→    }
311→
312→    /**
313→     * Builder for {@link HandleTracker}.
314→     */
315→    static final class Builder {
316→
317→        private int maxHandlesPerSourcePerTable = 16;
318→        private int maxHandlesPerTable = 64;
319→        private int maxTotalHandles = 1024;
320→        private AllocationTracking allocationTracking = AllocationTracking.OFF;
321→
322→        private Builder() {
323→        }
324→
325→        Builder maxHandlesPerSourcePerTable(int max) {
326→            assert max > 0 : "max must be positive";
327→            this.maxHandlesPerSourcePerTable = max;
328→            return this;
329→        }
330→
331→        Builder maxHandlesPerTable(int max) {
332→            assert max > 0 : "max must be positive";
333→            this.maxHandlesPerTable = max;
334→            return this;
335→        }
336→
337→        Builder maxTotalHandles(int max) {
338→            assert max > 0 : "max must be positive";
339→            this.maxTotalHandles = max;
340→            return this;
341→        }
342→
343→        Builder allocationTracking(AllocationTracking tracking) {
344→            Objects.requireNonNull(tracking, "tracking must not be null");
345→            this.allocationTracking = tracking;
346→            return this;
347→        }
348→
349→        HandleTracker build() {
350→            return new HandleTracker(this);
351→        }
352→    }
353→}
